unsigned patch_call_insn(void *insnbuf, const void *target, u16 tgt_clobbers,
                         unsigned long addr, u16 site_clobbers, unsigned len)
{
    long delta = (long)target - (long)addr - 5;

    if (len < 5)
        return len;

    *(unsigned char *)insnbuf = 0xe8; /* call <rel32> opcode */
    *(long *)(insnbuf + 1) = delta;

    return 5;
}

unsigned patch_call_insn(void *insnbuf, const void *target, u16 tgt_clobbers,
                         unsigned long addr, u16 site_clobbers, unsigned len)
{
    long delta = (long)target - (long)(addr + 5);
    if (len < 5) {
        // Instruction buffer is too small for a call patch
        return len;
    }

    // Set the opcode for a call instruction (0xE8 for x86 relative call)
    ((unsigned char *)insnbuf)[0] = 0xE8;
    *(long *)((unsigned char *)insnbuf + 1) = delta;

    return 5;
}

